import{z as l,x as i,o as A,c as C,q as n,j as r,D as a,d as e,s as o,S as s,b as B}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"季节性展期模式","description":"","frontmatter":{"title":"季节性展期模式","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ft-seasonal-patterns.md","filePath":"quant/ft-seasonal-patterns.md","lastUpdated":1791063341000}'),d={name:"quant/ft-seasonal-patterns.md"};function D(p,E,h,u,F,m){const t=i("Mermaid");return A(),C("div",null,[E[2]||(E[2]=n('<h1 id="季节性展期模式" tabindex="-1">季节性展期模式 <a class="header-anchor" href="#季节性展期模式" aria-label="Permalink to &quot;季节性展期模式&quot;">​</a></h1><div class="epigraph"><p>展期的季节不止一种：库存有季节，合约循环有季节，制度日程也有季节；三张日历叠起来，才知道哪些规律可交易，哪些只是日历的影子。</p><footer>—— Working, AER, 1949；季节与库存的证据见 Gorton, Hayashi and Rouwenhorst, Review of Finance, 2013；基差的预测内容见 Fama and French, Journal of Business, 1987</footer></div><p><a href="/quant/ft-calendar-arb-deep">上一课</a>把跨期价差写成带外加状态矛盾的判定，其中「避开滚仓窗与交割窗」一条还未展开，正是本课的对象。<a href="/quant/seasonal-roll">季节性展期</a>已把商品库存季节写成一课：收获与取暖季经库存改曲线。本课把「季节」扩展为模式语言：不只问曲线形态的季节，也问展期活动本身的季节——迁移集中在哪些周、价差在哪些月份宽、哪些时点必须让路。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>展期活动的季节成分有三类。其一，库存季节：收获、取暖、驾驶季经库存路径改曲线形态与近月波动，<a href="/quant/seasonal-roll">季节性展期</a>与 Gorton–Hayashi–Rouwenhorst 的证据都在这层。其二，合约循环季节：股指到期周五、国债季月的 CTD 切换段、商品的交割通知月，是制度安排的周期——迁移与价差波动跟着合约日历走，跟天气无关。其三，制度季节：指数年度调整、固定滚仓窗、保证金分档，规则可预期，流量就聚集，Mou 记录的抢跑前移是它的影子。</p><p><span class="marginnote">直觉类比：三类季节像三本挂历——库存季节是「农业挂历」，跟着收获与取暖走；循环季节是「交易所挂历」，跟着到期日走；制度季节是「指数公司挂历」，跟着规则修订走。三本叠起来看，才知道哪天是节日（拥挤）、哪天是平常日。</span></p><p>错在哪：三类机制塞进同一个月度哑变量回归，样本内显著、样本外消失；把循环季节当库存季节交易，会在交割月前做多本该避开的近月；把制度季节当恒定，规则一改模式立即失效。</p><h3 id="事件窗对齐而不是墙钟月份" tabindex="-1">事件窗对齐而不是墙钟月份 <a class="header-anchor" href="#事件窗对齐而不是墙钟月份" aria-label="Permalink to &quot;事件窗对齐而不是墙钟月份&quot;">​</a></h3><p>量化的正确对象是相对刻度。库存季节对齐「距收获的周数」或相对五年同期的库存分位；循环季节对齐「距最后交易日 / 通知日 / 到期周五的天数」；制度季节对齐指数方法论规定的窗口日。在各自刻度上做事件窗统计：宽度、深度、迁移完成度按相对日聚合，分制度断点前后检验稳定性，模式不重现的不入排程表。</p><p><span class="marginnote">术语翻译：「事件窗对齐」就是不按日历月份、而按「距某个事件还有几天」分组统计。不问「11 月的价差宽不宽」，而问「距收获还有 4 周时价差平均多宽」——不同年份的样本才能叠在同一把尺子上。</span></p><p><span class="marginnote">国债期货的季月循环给出循环季节的干净样本：CTD 切换与移仓集中在换月前后各一两周，价差波动与久期跳变同时出现——这与天气无关，与转换因子和回购特殊性有关，见<a href="/quant/ctd-cheapest">最便宜可交割</a>。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>产出物是一张季节排程表，与前几课对接。第一步，按品种列出三类季节的状态变量与刻度：库存分位（商品）、距条款日期天数（全部）、指数窗口日（被动品种）。第二步，事件窗统计：每个相对刻度上算<a href="/quant/ft-roll-cost-modeling">展期成本的建模</a>那套参数——两腿宽度、日历价差波动、深度，形成按季节分桶的成本表，替代年度平均。第三步，排程：迁移开始日避开最贵的相对日，截止日照第一课的日历，触发阈值照第四课的状态。第四步，稳定性：每季度重估一次，分样本期报告各模式的显著性，显著衰减的模式降权或删除。</p>',13)),(A(),r(s,null,{default:a(()=>[o(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20S1%5B%22%E5%BA%93%E5%AD%98%E5%AD%A3%E8%8A%82%EF%BC%9A%E8%B7%9D%E6%94%B6%E8%8E%B7%E5%91%A8%E6%95%B0%20%2F%20%E5%BA%93%E5%AD%98%E5%88%86%E4%BD%8D%22%5D%20--%3E%20BUCK%5B%22%E6%8C%89%E5%AD%A3%E8%8A%82%E5%88%86%E6%A1%B6%E7%9A%84%E6%88%90%E6%9C%AC%E5%8F%82%E6%95%B0%22%5D%0A%20%20S2%5B%22%E5%BE%AA%E7%8E%AF%E5%AD%A3%E8%8A%82%EF%BC%9A%E8%B7%9D%E6%9D%A1%E6%AC%BE%E6%97%A5%E6%9C%9F%E5%A4%A9%E6%95%B0%22%5D%20--%3E%20BUCK%0A%20%20S3%5B%22%E5%88%B6%E5%BA%A6%E5%AD%A3%E8%8A%82%EF%BC%9A%E6%8C%87%E6%95%B0%E7%AA%97%E5%8F%A3%E6%97%A5%22%5D%20--%3E%20BUCK%0A%20%20BUCK%20--%3E%20STAB%5B%22%E5%88%86%E6%A0%B7%E6%9C%AC%E6%9C%9F%E7%A8%B3%E5%AE%9A%E6%80%A7%E6%A3%80%E9%AA%8C%22%5D%0A%20%20STAB%20--%3E%7C%22%E6%A8%A1%E5%BC%8F%E7%A8%B3%E5%AE%9A%22%7C%20SCHED%5B%22%E5%AD%A3%E8%8A%82%E6%8E%92%E7%A8%8B%E8%A1%A8%EF%BC%9A%E8%BF%81%E7%A7%BB%E5%BC%80%E5%A7%8B%E6%97%A5%E4%B8%8E%E7%AA%97%E5%8F%A3%22%5D%0A%20%20STAB%20--%3E%7C%22%E6%A8%A1%E5%BC%8F%E8%A1%B0%E5%87%8F%22%7C%20DROP%5B%22%E9%99%8D%E6%9D%83%E6%88%96%E5%88%A0%E9%99%A4%22%5D%0A%20%20SCHED%20--%3E%20ROLL%5B%22%E6%8E%A5%E5%85%A5%E6%97%A5%E5%8E%86%E3%80%81%E6%88%90%E6%9C%AC%E4%B8%8E%E6%89%A7%E8%A1%8C%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[e("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,"三类季节的机制层次不同。库存季节是基本面：Working 的仓储函数使库存的条件均值随日历走，基差因而含可预期的季节成分，Fama 与 French（1987）在农产品上验证过基差的预测内容。循环季节是制度性聚集：合约循环把移仓需求压缩在固定时段，深度与宽度按合约日历而非墙钟重新分布——它可预期、可避开，但不提供方向。制度季节是规则与流量的合谋：窗口写入方法论，流量可预测，供给者与抢跑者把高峰前移；规则改，季节跟着改。三层只有第一层改条件期望，后两层改的是执行的时机与成本——把它们分清，季节信号才不会被错用成方向预测。",-1)),(A(),r(s,null,{default:a(()=>[o(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20INV%5B%22%E5%BA%93%E5%AD%98%E5%AD%A3%E8%8A%82%EF%BC%9A%E5%9F%BA%E6%9C%AC%E9%9D%A2%22%5D%20--%3E%20I1%5B%22%E6%94%B9%E6%9D%A1%E4%BB%B6%E6%9C%9F%E6%9C%9B%EF%BC%9A%E5%9F%BA%E5%B7%AE%E4%B8%8E%E5%B1%95%E6%9C%9F%E6%94%B6%E7%9B%8A%E7%9A%84%E5%9D%87%E5%80%BC%22%5D%0A%20%20I1%20--%3E%20USE%5B%22%E5%8F%AF%E7%94%A8%E4%BA%8E%E6%8C%81%E6%9C%89%E4%B8%8E%E6%96%B9%E5%90%91%E5%88%A4%E6%96%AD%22%5D%0A%20%20CYC%5B%22%E5%BE%AA%E7%8E%AF%E5%AD%A3%E8%8A%82%EF%BC%9A%E5%88%B6%E5%BA%A6%E8%81%9A%E9%9B%86%22%5D%20--%3E%20C1%5B%22%E4%B8%8D%E6%94%B9%E6%96%B9%E5%90%91%EF%BC%9A%E5%8F%AA%E5%8E%8B%E7%BC%A9%E8%BF%81%E7%A7%BB%E6%97%B6%E6%AE%B5%22%5D%0A%20%20C1%20--%3E%20AVOID%5B%22%E7%94%A8%E4%BA%8E%E9%81%BF%E5%BC%80%EF%BC%9A%E9%94%99%E6%97%A5%E6%89%A7%E8%A1%8C%E7%9C%81%E6%88%90%E6%9C%AC%22%5D%0A%20%20REG%5B%22%E5%88%B6%E5%BA%A6%E5%AD%A3%E8%8A%82%EF%BC%9A%E8%A7%84%E5%88%99%E4%B8%8E%E6%B5%81%E9%87%8F%22%5D%20--%3E%20R1%5B%22%E4%B8%8D%E6%94%B9%E6%96%B9%E5%90%91%EF%BC%9A%E8%A7%84%E5%88%99%E4%B8%80%E6%94%B9%E7%AB%8B%E5%8D%B3%E9%87%8D%E6%8E%92%22%5D%0A%20%20R1%20--%3E%20AVOID%0A%20%20USE%20--%3E%20Z%5B%22%E5%85%88%E5%88%86%E5%B1%82%EF%BC%8C%E5%86%8D%E5%86%B3%E5%AE%9A%E5%AD%A3%E8%8A%82%E4%BF%A1%E5%8F%B7%E6%80%8E%E4%B9%88%E7%94%A8%22%5D%0A%20%20AVOID%20--%3E%20Z%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=n('<p><span class="marginnote">常见误区：拿三十个月的数据跑月度哑变量，宣布发现「显著季节模式」。三十个观测摊给 12 个月，每月不到 3 个——等于用三个样本点断言季节规律，样本外多半消失。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>制度漂移是主要威胁：种植带北移与气候改变农业季节，页岩改写天然气的季节振幅，指数规则修订重排窗口季节。季节是条件均值，不是每年的保证：报告意外与天气冲击随时覆盖季节基线。数据不足的月份与品种不硬估——三十个观测的「季节模式」是噪声。本课输出的是排程与分桶参数，不重新定义展期收益；库存季节对合约选择本身的含义，以<a href="/quant/seasonal-roll">季节性展期</a>的口径为准。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>展期的季节分三类：库存季节改曲线与波动，循环季节压缩迁移时段，制度季节聚集流量。</li><li>量化用事件窗对齐相对刻度（距收获、距条款日期、距窗口日），不用墙钟月份哑变量。</li><li>产出是季节排程表加按季节分桶的成本参数，接入日历、成本与执行三张表。</li><li>分样本期检验稳定性；制度修订与气候漂移都会使旧季节失效。</li><li>只有库存季节改条件期望，循环与制度季节改执行时机——季节信号不是方向预测。</li><li>出处：Working, <em>AER</em>, 1949；Fama and French, <em>Journal of Business</em>, 1987；Gorton, Hayashi and Rouwenhorst, <em>Review of Finance</em>, 2013；Mou, 2011。</li></ul>',5))])}const _=l(d,[["render",D]]);export{c as __pageData,_ as default};
